// pedidos processing modificados en las ultimas 48h (misma ventana que cwFacturaSweep01)
const d = new Date(Date.now() - 48*3600*1000);
const pad = n => String(n).padStart(2,'0');
const iso = d.getUTCFullYear()+'-'+pad(d.getUTCMonth()+1)+'-'+pad(d.getUTCDate())+'T'+pad(d.getUTCHours())+':'+pad(d.getUTCMinutes())+':'+pad(d.getUTCSeconds());
return [{ json: { modified_after: iso } }];

// Candidatos: Coordinadora, sin guia y fuera de la gracia.
// El filtro se repite aqui aunque el endpoint tambien decida: asi no se
// dispara una peticion por cada pedido sano cada 15 minutos.
// Corre en modo "once for all items": $json resolveria al primer item por
// casualidad (no por contrato), asi que se usa $input.first().json explicito.
//
// C3: ademas clasifica la consulta a WC en tres situaciones y las propaga
// para que Resumen pueda avisar cuando el barredor se quedo ciego, no solo
// cuando hay pedidos rendidos. Si no hay candidatos reales (consulta sana
// vacia, o consulta fallida) devuelve un unico item "de estado" con
// order_id:null -- Barrer guia lo llama igual (Coordinadora responde 404
// "Pedido no encontrado", inofensivo, y Resumen lo excluye de revisados y
// fallos) solo para que Resumen corra; ver alwaysOutputData en este nodo,
// que cubre ademas el caso de que el codigo truene antes de este return.
const GRACIA_MIN = 10;
const inputJson = $input.first().json;
const statusCode = inputJson ? inputJson.statusCode : undefined;
const body = inputJson ? inputJson.body : undefined;
const esLista = Array.isArray(body);
// consulta fallida: HTTP distinto de 200, o el body no es la lista de
// pedidos que espera WooCommerce (credencial ausente, 401/500, el WAF del
// hosting devolviendo HTML, etc.) -- sin este chequeo esa lista vacia por
// defecto se confunde con "sin candidatos" (sano) y la pasada queda muda.
const consultaFallida = 200 !== statusCode || !esLista;
const list = esLista ? body : [];
// I3: la pagina vino llena (per_page=40): puede haber pedidos mas antiguos
// -- justo los que mas llevan sin guia -- fuera de esta pagina.
const paginaLlena = esLista && list.length >= 40;
const out = [];
if (!consultaFallida) {
  for (const o of list) {
    if (!o || o.status !== 'processing') continue;
    const ship = (o.shipping_lines || []).map(s => String(s.method_id || '') + ' ' + String(s.method_title || ''));
    if (!ship.some(s => s.toLowerCase().indexOf('coordinadora') !== -1)) continue;
    const meta = {};
    for (const m of (o.meta_data || [])) meta[m.key] = m.value;
    if (String(meta['_coordinadora_tracking_number'] || '').trim() !== '') continue;
    // Fecha base para medir la gracia: pagado; si falta, creado -- mismo
    // criterio que sweep_minutos() en includes/class-ccmck-guias.php. Sin esta
    // caida, un pedido sin date_paid_gmt se descartaba aqui para siempre: nunca
    // llegaba al endpoint, nunca acumulaba intentos, nunca alcanzaba el motivo
    // 'agotados los reintentos' y por tanto nunca disparaba el aviso por correo
    // -- quedaba pagado, sin rotulo y en silencio para siempre.
    const fechaBase = o.date_paid_gmt || o.date_created_gmt;
    if (!fechaBase) continue;
    const base = Date.parse(fechaBase + 'Z');
    if (!base) continue;
    const minutos = Math.floor((Date.now() - base) / 60000);
    if (minutos < GRACIA_MIN) continue;
    out.push({ json: { order_id: o.id, numero: o.number, minutos, total: o.total, consulta_fallida: false, motivo_consulta: '', pagina_llena: paginaLlena } });
  }
}
if (out.length > 0) return out;
// Sin candidatos reales (consulta sana y vacia, o consulta fallida): un
// unico item de estado para que Resumen sepa por que, y para que el resto
// de la cadena corra (ver alwaysOutputData en este nodo).
return [{ json: {
  order_id: null,
  consulta_fallida: consultaFallida,
  motivo_consulta: consultaFallida ? ('HTTP ' + (statusCode || 0) + (esLista ? '' : ', body no es una lista de pedidos')) : '',
  pagina_llena: paginaLlena,
} }];

// Resume la pasada y separa a quien merece correo -- lo que se rindio por
// primera vez (I2), mas dos motivos nuevos que propaga "Candidatos sin guia"
// (C3, I3): que la consulta a WC haya fallado, o que la pagina haya venido
// llena. En los tres casos el barredor puede estar ciego a pedidos reales y
// hay que decirlo, no callarlo.
const MAX_INTENTOS = 3;   // igual que CCMCK_Guias::SWEEP_MAX_INTENTOS
const all = $input.all();
// Candidatos de la pasada anterior, en el MISMO orden en que entraron a
// "Barrer guia" (no hay filtro entre medias): sirve para recuperar el
// order_id cuando la respuesta no trae body (fallo de red real, ver abajo),
// y para leer el estado de la consulta que propaga ese nodo (C3/I3).
// pairedItem.item es el indice de origen que mantiene n8n aunque el request
// falle; el indice del bucle es solo el respaldo si por lo que sea no viene.
const candidatos = $('Candidatos sin guía').all();

// Estado de la consulta a WC: viene identico en cada candidato real, o solo
// en el item placeholder (order_id:null) cuando no hubo ninguno -- basta
// mirar el primero.
const estadoConsulta = candidatos[0] ? candidatos[0].json : {};
const consultaFallida = !!estadoConsulta.consulta_fallida;
const motivoConsulta = String(estadoConsulta.motivo_consulta || '');
const paginaLlena = !!estadoConsulta.pagina_llena;

let revisados = 0;
const hechas = [];
const rendidos = [];
const fallos = [];
for (let i = 0; i < all.length; i++) {
  const it = all[i];
  const j = it.json || {};
  const origenIdx = (it.pairedItem && typeof it.pairedItem.item === 'number') ? it.pairedItem.item : i;
  const candidato = candidatos[origenIdx] && candidatos[origenIdx].json;
  // El item placeholder (order_id:null) llega hasta "Barrer guia" para que
  // este nodo corra sin candidatos reales (alwaysOutputData en "Candidatos
  // sin guia"), pero no es un pedido: su 404 no es un fallo real, ya se
  // reporta arriba via consultaFallida/paginaLlena. Se excluye tambien de
  // "revisados": cero pedidos reales se miraron en esta pasada.
  if (candidato && candidato.order_id === null) continue;
  revisados++;
  const orderIdCandidato = candidato ? candidato.order_id : undefined;
  // Con onError: continueRegularOutput, un fallo de red real (timeout, DNS,
  // conexion rechazada -- no un HTTP 4xx/5xx, que neverError ya deja pasar
  // como respuesta normal) llega aqui como { error: "..." }, sin body ni
  // statusCode. Sin este chequeo no cae en ninguna rama de abajo: se pierde
  // en silencio y solo cuenta en "revisados". Aqui el silencio no es exito.
  if (j.error !== undefined && j.body === undefined) {
    fallos.push({ cod: 0, error: String(j.error).slice(0, 120), order_id: orderIdCandidato });
    continue;
  }
  const b = j.body || {};
  const cod = j.statusCode || 0;
  if (b.ok === true) { hechas.push(b.guia); continue; }
  if (b.skipped === true) {
    // I2: solo cuenta como "rendido" (y por tanto dispara correo) la
    // primera vez -- si alerta_enviada viene true, rest_sweep() ya marco la
    // meta _ccmck_guia_alerta_enviada en una pasada anterior y el correo ya
    // salio; repetirlo aqui son los ~96 correos/dia que motivaron este fix.
    if (b.reason === 'agotados los reintentos' && b.alerta_enviada !== true) {
      rendidos.push({ intentos: b.intentos, order_id: b.order_id !== undefined ? b.order_id : orderIdCandidato });
    }
    continue;
  }
  if (cod >= 400) {
    // rest_sweep() manda order_id como 3er argumento de WP_Error; WordPress
    // lo anida bajo "data" al convertirlo a respuesta REST.
    const orderIdFallo = (b && b.data && b.data.order_id !== undefined) ? b.data.order_id : orderIdCandidato;
    fallos.push({ cod, error: String((b && b.message) || '').slice(0, 120), order_id: orderIdFallo });
  }
}
return [{ json: {
  revisados,
  generadas: hechas.length,
  guias: hechas,
  rendidos: rendidos.length,
  fallos: fallos.length,
  max_intentos: MAX_INTENTOS,
  detalle_rendidos: rendidos.slice(0, 5),
  detalle_fallos: fallos.slice(0, 5),
  consulta_fallida: consultaFallida,
  motivo_consulta: motivoConsulta,
  pagina_llena: paginaLlena,
} }];

